import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import FieldSet from 'flarum/common/components/FieldSet';
export default class PWAUploadFirebaseConfigForm extends Component {
  view() {
    return m("form", {
      onsubmit: e => this.updateFirebaseConfig(e)
    }, m(FieldSet, {
      label: app.translator.trans('fof-pwa.admin.pwa.firebase_config.heading'),
      description: app.translator.trans('fof-pwa.admin.pwa.firebase_config.help_text', {
        a: m("a", {
          href: "https://docs.pwabuilder.com/#/builder/app-store?id=push-notifications",
          target: "_blank",
          rel: "noopener noreferrer"
        })
      })
    }, m("label", {
      className: "Button"
    }, app.translator.trans('fof-pwa.admin.pwa.firebase_config.upload_file'), m("input", {
      type: "file",
      accept: ".json",
      hidden: true,
      onchange: e => this.updateFirebaseConfig(e)
    }))));
  }
  updateFirebaseConfig(event) {
    const input = event.target;
    const file = input.files?.[0];
    if (!file) return;
    const body = new FormData();
    body.append('file', file);
    app.request({
      method: 'POST',
      url: `${app.forum.attribute('apiUrl')}/pwa/firebase-config`,
      body
    }).then(() => {
      app.alerts.show({
        type: 'success'
      }, app.translator.trans('fof-pwa.admin.pwa.firebase_config.upload_successful'));
      input.value = '';
    });
  }
}
flarum.reg.add('fof-pwa', 'admin/components/PWAUploadFirebaseConfigForm', PWAUploadFirebaseConfigForm);